def resolve(path, cwd, links):
    # Start with cwd if path is relative, otherwise start with empty
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split the path into components
    components = path.split('/')

    # Track link count to prevent infinite loops
    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this path is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # If target is absolute, start from root
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace current components with target components + remaining
            components = target_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Return the result, ensuring no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

